reference_css:
* { box-sizing: border-box; }
:root { --ink: #1c1917; --muted: #57534e; --line: #d6d3d1; --paper: #fffcf7; --accent: #9a3412; }
body { margin: 0; color: var(--ink); background: var(--paper); font: 1.05rem/1.75 Georgia, "Times New Roman", serif; }
.site-header { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 1rem; padding: 1rem max(1rem, calc((100vw - 72rem) / 2)); border-bottom: 1px solid var(--line); }
.brand { font-family: system-ui, sans-serif; font-weight: 850; text-decoration: none; }
.site-header nav { display: flex; flex-wrap: wrap; gap: 1rem; font-family: system-ui, sans-serif; }
.page-shell { width: min(calc(100% - 2rem), 72rem); margin-inline: auto; }
.article { display: grid; grid-template-columns: minmax(0, 1fr) 14rem; gap: 2rem; padding-block: clamp(2rem, 5vw, 4rem); }
.article-header, .editorial-figure, .article-body { grid-column: 1; }
.article-header h1 { max-width: 16ch; font-size: clamp(2.5rem, 6vw, 5rem); line-height: 1.05; letter-spacing: -.035em; }
.article-deck { font-size: 1.3rem; line-height: 1.4; color: var(--muted); max-width: 48ch; }
.eyebrow, .article-meta, .author-card { font-family: system-ui, sans-serif; }
.eyebrow { color: var(--accent); font-size: .78rem; letter-spacing: .12em; text-transform: uppercase; font-weight: 800; }
.article-meta { display: flex; flex-wrap: wrap; gap: .75rem 1.25rem; color: var(--muted); font-size: .85rem; }
.editorial-art { aspect-ratio: 16 / 8; border-radius: .75rem; background: linear-gradient(145deg, #d6d3d1 0 35%, #a8a29e 35% 55%, #78716c 55% 75%, #f5f5f4 75%); }
figcaption { color: var(--muted); font-size: .9rem; margin-block-start: .5rem; }
.article-body { max-width: 68ch; }
.article-body h2 { margin-block-start: 2.5rem; line-height: 1.2; }
.pull-quote { margin-inline: 0; padding-inline-start: 1.25rem; border-inline-start: 4px solid var(--accent); font-size: clamp(1.4rem, 3vw, 2rem); line-height: 1.35; }
.author-card { align-self: start; grid-column: 2; grid-row: 2 / span 2; padding: 1rem; border: 1px solid var(--line); border-radius: .75rem; font-size: .9rem; }
:focus-visible { outline: 3px solid #1d4ed8; outline-offset: 3px; }
@media (max-width: 52rem) { .article { grid-template-columns: minmax(0, 1fr); } .author-card { grid-column: 1; grid-row: auto; } }
@media print { .site-header nav, .author-card { display: none; } body { color: #000; background: #fff; font-size: 12pt; } .article { display: block; max-width: none; } a { text-decoration: underline; } }
